  }
  std::istringstream iss(temperatureRangePair.second);
  double temperatureRange;
  iss >> temperatureRange;
  if (!iss) {
    return false;
  }
  if (temperatureRange < -100 || temperatureRange > 100) {
    return false;
  }
  return true;
}

